function Palette() {
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        setOpen((v) => !v);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);
  return (
    <CommandPalette
      open={open}
      onOpenChange={setOpen}
      groups={[
        { heading: "Navigation", commands: [
          { id: "home", label: "Go to home", shortcut: "G H", onSelect: () => navigate("/") },
          { id: "settings", label: "Open settings", hint: "/settings", onSelect: () => navigate("/settings") },
        ] },
        { heading: "Actions", commands: [
          { id: "new", label: "New project", keywords: ["create"], onSelect: () => createProject() },
        ] },
      ]}
    />
  );
}

